source("pre.R")
kw <- jwk_oct(as.raw(1:16), kid = "kw", alg = "A128KW")
R <- function(label, expr) { r <- try_(expr); cat(sprintf("%-46s", label)); if (inherits(r, "err")) cat("ERR", r$cls[1], "|", r$msg, "\n") else cat("ok:", if (is.raw(r)) rawToChar(r) else r, "\n"); invisible(r) }
t1 <- R("emit unprotected zip (flattened)", jwe_encrypt("plain text", kw, unprotected = list(zip = "DEF"), format = "flattened"))
R("  self-decrypt", jwe_decrypt(t1, kw, "A128KW", "A128CBC-HS256")$plaintext)
t2 <- R("emit recipient zip (general)", jwe_encrypt("plain text", list(jwe_recipient(kw, header = list(zip = "DEF"))), format = "general"))
R("  self-decrypt", jwe_decrypt(t2, kw, "A128KW", "A128CBC-HS256")$plaintext)
t3 <- R("emit recipient zip (flattened)", jwe_encrypt("plain text", list(jwe_recipient(kw, header = list(zip = "DEF"))), format = "flattened"))
R("  self-decrypt", jwe_decrypt(t3, kw, "A128KW", "A128CBC-HS256")$plaintext)
R("emit protected zip", jwe_encrypt("plain text", kw, header = list(zip = "DEF")))
R("emit protected enc", jwe_encrypt("plain text", kw, header = list(enc = "A128GCM")))
# JWS: duplicate header names
k <- jwk_oct(as.raw(1:32))
t <- jws_sign("p", k, "HS256", header = list(a = 1, a = 2)); cat("JWS dup header ->", rawToChar(zujose:::b64url_decode(strsplit(t, ".", fixed = TRUE)[[1]][1], "x", NULL)), "\n")
t <- try_(jws_sign("p", k, "HS256", header = list(kid = "x", kid = "y"))); cat("JWS dup kid ->", if (inherits(t, "err")) t$msg else rawToChar(zujose:::b64url_decode(strsplit(t, ".", fixed = TRUE)[[1]][1], "x", NULL)), "\n")
t <- try_(jws_sign("p", k, "HS256", unprotected = list(a = 1, a = 2), format = "flattened")); cat("JWS dup unprotected ->", if (inherits(t, "err")) t$msg else t, "\n")
t <- try_(jwt_encode(list(), k, "HS256", header = list(typ = "JWT", typ = "at+jwt"), issued_at = FALSE)); cat("JWT dup typ ->", if (inherits(t, "err")) t$msg else rawToChar(zujose:::b64url_decode(strsplit(t, ".", fixed = TRUE)[[1]][1], "x", NULL)), "\n")
cat("zujson dup:", zujson::json_write(list(a = 1, a = 2)), "\n")
t <- try_(jwe_encrypt("p", kw, unprotected = list(a = 1, a = 2), format = "flattened")); cat("JWE dup unprotected ->", if (inherits(t, "err")) t$msg else t, "\n")
writeLines(c(t1, t2), "p12_tokens.txt")
